"""Renders a results report from computed values. Pure formatting: no numbers are made up here."""
from __future__ import annotations

from typing import Any


def _n(v: Any, digits: int = 2, unit: str = "") -> str:
    return "n/a" if v is None else f"{v:,.{digits}f}{unit}"


def render_markdown(params: dict, verification: dict, summary: dict, quality: dict, lead: dict | None) -> str:
    m, c = summary["metrics"], summary["coverage"]
    L = [f"# WindWise results — {params['start']} to {params['end']} (delivery dates)", "",
         "_Generated by `python -m scripts.generate_results` from live Elexon BMRS data. Do not edit by hand._", "",
         "## Run parameters",
         f"- Retrieved at (UTC): {params['retrieved_at']}",
         f"- Decision cutoff: {params['cutoff_local_time']} Europe/London, {params['cutoff_days_before']} day(s) before delivery "
         "(**assumption**, not defined by the assignment)",
         f"- Forecast publish window fetched (UTC): {params['publish_from']} → {params['publish_to']}",
         f"- Evaluation resolution: {params['resolution']['minutes']} min — {params['resolution']['method']}", "",
         "## Source verification (observed in the responses)",
         f"- FUELHH WIND rows: {verification['actual_rows']}; fields: {verification['actual_fields']}; fuel types seen: {verification['actual_fuel_types']}",
         f"- FUELHH start-minute values: {verification['actual_start_minutes']}; generation range: {verification['actual_range_mw']} MW",
         f"- WINDFOR rows: {verification['forecast_rows']}; fields: {verification['forecast_fields']}",
         f"- WINDFOR start-minute values: {verification['forecast_start_minutes']}; generation range: {verification['forecast_range_mw']} MW",
         f"- WINDFOR publishTime range: {verification['publish_range']}",
         "- Still to confirm from Elexon documentation: that `startTime` is the interval **start** in both datasets, and that generation is MW (mean over the interval).", "",
         "## Accuracy metrics (matched intervals only; error = forecast − actual, MW)",
         "| Metric | Value |", "|---|---|",
         f"| MAE | {_n(m['mae_mw'], 1, ' MW')} |", f"| RMSE | {_n(m['rmse_mw'], 1, ' MW')} |",
         f"| Bias | {_n(m['bias_mw'], 1, ' MW')} |", f"| Median absolute error | {_n(m['median_abs_error_mw'], 1, ' MW')} |",
         f"| MAPE | {_n(m['mape_pct'], 2, '%')} (n={m['mape_n']}, {m['mape_excluded_zero_actual']} zero-actual excluded) |", "",
         "## Coverage",
         "| Item | Count |", "|---|---|",
         f"| Expected intervals | {c['expected_intervals']} |", f"| Actual intervals | {c['actual_intervals']} |",
         f"| Intervals with a forecast available at cutoff | {c['forecast_intervals']} |",
         f"| **Matched (used in metrics)** | **{c['matched_intervals']}** |",
         f"| Missing forecast | {c['missing_forecast_intervals']} |", f"| Missing actual | {c['missing_actual_intervals']} |",
         f"| Only post-cutoff forecasts existed | {c['intervals_with_only_later_forecasts']} |", "",
         "## Data quality",
         f"- Invalid actual / forecast records: {quality['invalid_actual_records']} / {quality['invalid_forecast_records']}",
         f"- Duplicates collapsed (actual / forecast): {quality['duplicate_actual_records_collapsed']} / {quality['duplicate_forecast_records_collapsed']}; conflicting forecast duplicates: {quality['conflicting_forecast_duplicates']}"]
    L += [f"- ⚠ {w}" for w in quality["warnings"]]
    L += ["", "## Forecast publication-time limitations"]
    if lead:
        L.append(f"- Selected-forecast lead time (delivery − publish), hours: min {_n(lead['min'], 1)}, median {_n(lead['median'], 1)}, max {_n(lead['max'], 1)}")
    L += ["- Only forecasts published at or before the cutoff are used; later (often more accurate) revisions are deliberately excluded.",
          "- Results depend on the assumed cutoff; changing it changes the selected forecasts and the metrics.",
          "- One month of data does not establish long-term forecast performance.", "",
          "## Daily summary", "| Date | Matched/Expected | MAE (MW) | RMSE (MW) | Bias (MW) |", "|---|---|---|---|---|"]
    for d in summary["daily"]:
        L.append(f"| {d['delivery_date']} | {d['matched_intervals']}/{d['expected_intervals']} | {_n(d['mae_mw'], 1)} | {_n(d['rmse_mw'], 1)} | {_n(d['bias_mw'], 1)} |")
    return "\n".join(L) + "\n"
